import {BM_DEPARTMENTS} from './bm-model.mjs';
import {MS_DEPARTMENTS} from './ms-model.mjs';
import {ASDA_DEPARTMENTS} from './asda-model.mjs';
import {DEPARTMENTS} from './catalogue-model.mjs';
import {CATALOGUE_GROUPS} from './catalogue-navigation.mjs';
import {monitorLabel} from './monitor-labels.mjs';
(()=>{
 const groups=[...CATALOGUE_GROUPS.map(g=>({...g,zh:'The Range · '+g.zh})),{id:'asda',zh:'ASDA · George 圣诞产品',en:'Christmas products',children:ASDA_DEPARTMENTS.map(d=>d.id)},{id:'bm',zh:'B&M 圣诞产品',en:'Christmas products',children:BM_DEPARTMENTS.map(d=>d.id)},{id:'ms',zh:'M&S 圣诞产品',en:'Christmas products',children:MS_DEPARTMENTS.map(d=>d.id)}];
 document.getElementById('mailScopes').innerHTML=groups.map(g=>'<details class="mailScopeGroup"><summary>'+g.zh+'<small>'+g.en+'</small></summary>'+[...(g.id==='themes'?['themes']:[]),...g.children].map(id=>{const d=DEPARTMENTS.find(d=>d.id===id);return '<label><input type="checkbox" name="mailScope" value="'+d.id+'" checked> '+d.label+'</label>';}).join('')+'</details>').join('');
 const el=id=>document.getElementById(id),local=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});let api='',dirty=false,config={intervalDays:7,time:'00:00'};
 const message=(id,text)=>{el(id).textContent=text};
 async function request(path,body,secret){const r=await fetch(api+path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'content-type':'application/json'}),...(secret?{authorization:'Bearer '+secret}:{})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const result=await r.json();if(!r.ok)throw Error(result.error||'云端操作未完成');return result}
 function show(c,force=false){config=c;el('automationTitle').dataset.schedule=`每隔${c.intervalDays||7}天，北京时间${c.time||'00:00'}启动`;if(!dirty||force){el('intervalDays').value=String(c.intervalDays||7);const [h,m]=(c.time||'00:00').split(':');el('runHour').value=h;el('runMinute').value=m;}message('scheduleState',`云端计划 · Cloud schedule：每隔${c.intervalDays||7}天 / Every ${c.intervalDays||7} days，北京时间 / Beijing ${c.time||'00:00'}。${c.nextRunAt?'下一次 · Next: '+local(c.nextRunAt):''}`)}
 async function refresh(){try{const [state,m]=await Promise.all([request('/public/status'),fetch('monitor-state.json',{cache:'no-store'}).then(r=>r.json())]);Object.assign(m,state.monitor||{});show(state.config);el('subscribeButton').disabled=!state.mailReady;message('mailState',state.mailReady?'确认邮箱后接收有新品的邮件；没有新品不发消息。No new products, no email.':'邮件服务暂不可用，不会虚报发送成功。');message('monitorState',`每天北京时间07:00启动检查 · Daily check at 07:00 Beijing${state.dispatchClock?.enabled?' · 独立云端定时已连接 · Independent scheduler connected':''}${state.dispatchClock?.lastStatus>=400?' · 定时触发异常 · Dispatch error HTTP '+state.dispatchClock.lastStatus:''} · ${monitorLabel(m)}${m.nextRunAt?' · 下一次 · Next: '+local(m.nextRunAt):''}${m.lastSuccess?' · 最近成功 · Last success: '+local(m.lastSuccess):''}${m.lastError?' · '+m.lastError:''}。ASDA · 最近检查 / Last check: ${state.asdaMonitor?.observedAt?local(state.asdaMonitor.observedAt):'基线准备中 / Baseline pending'}。M&S · 最近检查 / Last check: ${state.msMonitor?.observedAt?local(state.msMonitor.observedAt):'基线准备中 / Baseline pending'}。B&M · 最近检查 / Last check: ${state.bmMonitor?.observedAt?local(state.bmMonitor.observedAt):'基线准备中 / Baseline pending'}。仅首次发现的新品通过SKU和图片核验后发送，已有商品不重复发。`)}catch(e){message('monitorState','监测状态暂时不可达：'+e.message)}}
 el('scheduleForm').addEventListener('change',()=>{dirty=true});
 el('scheduleForm').addEventListener('submit',async e=>{e.preventDefault();const days=el('intervalDays').value||'7',time=el('intervalDays').value?el('runHour').value+':'+el('runMinute').value:'00:00';el('saveSchedule').disabled=true;try{if(!api)throw Error('云端设置服务尚未连接；当前仍执行已公布的默认7天00:00计划。');const secret=el('adminCode').value.trim();if(!secret)throw Error('请输入管理员访问码，防止其他访客修改你的云端更新计划。');const result=await request('/admin/schedule',{intervalDays:Number(days),time},secret);dirty=false;show(result.config,true);message('scheduleResult',result.message);el('adminCode').value=''}catch(err){message('scheduleResult',err.message)}finally{el('saveSchedule').disabled=false}});
 el('subscribeForm').addEventListener('submit',async e=>{e.preventDefault();el('subscribeButton').disabled=true;try{if(!api)throw Error('邮件服务尚未连接，尚未保存订阅。');const scopes=[...document.querySelectorAll('input[name=mailScope]:checked')].map(x=>x.value);if(!scopes.length)throw Error('请至少选择一个分类 · Choose at least one department.');const result=await request('/subscribe',{email:el('subscriberEmail').value.trim(),scopes});message('subscribeResult',result.message+(result.message?.includes('确认邮件已发送')?' Confirmation email sent; check your inbox.':result.message?.includes('已有已确认')?' This email is already confirmed.':result.message?.includes('取消')?' Subscription cancelled.':''));el('subscriberEmail').value=''}catch(err){message('subscribeResult',err.message)}finally{el('subscribeButton').disabled=!api}});
 el('unsubscribeButton').addEventListener('click',async()=>{if(!el('subscriberEmail').reportValidity())return;el('unsubscribeButton').disabled=true;try{if(!api)throw Error('云端订阅服务尚未连接。');const result=await request('/unsubscribe-by-email',{email:el('subscriberEmail').value.trim()});message('subscribeResult',result.message+(result.message?.includes('确认邮件已发送')?' Confirmation email sent; check your inbox.':result.message?.includes('已有已确认')?' This email is already confirmed.':result.message?.includes('取消')?' Subscription cancelled.':''));el('subscriberEmail').value=''}catch(e){message('subscribeResult',e.message)}finally{el('unsubscribeButton').disabled=!api}});
 async function init(){try{const [service,saved]=await Promise.all([fetch('service.json',{cache:'no-store'}).then(r=>r.json()),fetch('settings.json',{cache:'no-store'}).then(r=>r.json())]);show(saved);api=(service.apiBase||'').replace(/\/$/,'');el('unsubscribeButton').disabled=!api;if(api){await refresh();setInterval(refresh,60000)}else{message('monitorState','每日新品检查：每天北京时间07:00启动，邮件服务连接完成后启用。');message('mailState','邮件服务尚在连接，订阅尚未启用，不会虚报发送成功。');el('subscribeButton').disabled=true}}catch(e){message('scheduleState','读取云端计划失败，请刷新重试。')}}
 init();
})();
